{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C38"],
      "claim": "The closest analogue, rilzabrutinib (Morgan 0.5152), shares the same pyrazolo[3,4-d]pyrimidine core, phenoxyphenyl group, and piperidine linker as the query; its measured absolute oral bioavailability in humans was <5% (0.047), far below the 20% threshold, providing strong direct evidence that this scaffold has low oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Acalabrutinib, another BTK inhibitor with lower structural similarity (Morgan 0.2427), had an absolute oral bioavailability of 25.3% in healthy subjects, above the threshold; this is contradictory evidence but is outweighed by the much closer rilzabrutinib analogue and by the query's known extensive first-pass metabolism.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is structurally very close to rilzabrutinib, whose human absolute oral bioavailability is consistently about 4.7% (<5%), far below the 20% threshold. Although a more distant BTK inhibitor (acalabrutinib) reaches 25%, the close analogue evidence and the shared scaffold's very low F strongly support a low bioavailability prediction, even under fed conditions.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement for the query molecule itself under fed conditions is available.",
    "The closest analogue rilzabrutinib was dosed as a tablet without explicit fed/fasted state, but its very low F (<5%) makes it unlikely that food would raise F above 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

